import { DEFAULT_ROLE, checkEmail, checkName, checkRole, normalizeEmail, normalizeName } from '../validation/user.js';

export function createUser(store, request) {
  const body = request.body ?? {};

  const email = normalizeEmail(body.email);
  const name = normalizeName(body.name);
  const role = body.role === undefined ? DEFAULT_ROLE : body.role;

  const messages = [checkEmail(email), checkName(name), checkRole(role)].filter(Boolean);
  if (messages.length > 0) {
